/** Build the public-facing Tawdheef site beside the local tracker and as a
 * separate static release. No private tracker data is read by this build. */
import { readFile, writeFile, mkdir, cp, readdir, stat, unlink } from 'node:fs/promises';
import { resolve, dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import JSZip from 'jszip';
import { sourceArchive, checkPublicSource } from '../scripts/release-files.mjs';
import { packageBrand } from '../scripts/branding/package-assets.mjs';
import { loadGuides, createGuidePages, aboutPage } from './guides.mjs';
import { walkthrough } from './walkthrough.mjs';

const root=resolve(dirname(fileURLToPath(import.meta.url)),'..');
await packageBrand(root);
const config=JSON.parse(await readFile(join(root,'website/config.json'),'utf8'));
const firstRunGuide=await readFile(join(root,'docs/FIRST-RUN.md'),'utf8');
const guides=await loadGuides(root);
const aboutMarkdown=await readFile(join(root,'website/about.md'),'utf8');
const firstRunPrompt=firstRunGuide.match(/^> (Set up Tawdheef[^\r\n]+)$/m)?.[1];
if(!firstRunPrompt)throw new Error('The first-run guide must include its copyable setup request.');
const source=JSON.parse(await readFile(join(root,'data/uae-directory.json'),'utf8'));
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const count=source.records.length;
const date='10 November 2026';
const profile=config.githubProfile;
const catalog=JSON.parse(await readFile(join(root,'directories/catalog.json'),'utf8'));
const packs=catalog.packs;
const featuredPacks=packs.filter(pack=>pack.featured!==false&&!pack.historical);
const packIndices=new Map(await Promise.all(featuredPacks.map(async pack=>[pack.id,JSON.parse(await readFile(join(root,'directories',pack.id,pack.files.index),'utf8'))])));
const countryTitle=pack=>pack.country==='AE'?'UAE':pack.name;
const repository=config.intendedRepository;
const releaseTag=config.releaseTag;
if(!/^v\d+\.\d+\.\d+(?:-[a-z0-9.-]+)?$/.test(releaseTag))throw new Error('Set a reviewed releaseTag in website/config.json.');
const releaseUrl=repository+'/releases/tag/'+releaseTag;
const releaseDownload=file=>repository+'/releases/download/'+releaseTag+'/'+file;
const sourceDownload=config.repositoryPublished?releaseDownload('tawdheef-'+releaseTag.slice(1)+'-source.zip'):'/downloads/tawdheef-source.zip';
const repositoryHome=config.repositoryPublished?repository:profile;
const contributeUrl=config.repositoryPublished?repository+'/blob/main/CONTRIBUTING.md':'/downloads/directory-contributing.md';
const policyUrl=file=>config.repositoryPublished?repository+'/blob/main/'+file:'/downloads/policies/'+file.split('/').at(-1);
const packDownload=pack=>config.repositoryPublished?releaseDownload(pack.download.split('/').at(-1)):'/downloads/'+pack.download.split('/').at(-1);
const dataIssueUrl=repository+'/issues/new?template=directory-data.yml';
const countryIssueUrl=repository+'/issues/new?template=new-country-pack.yml';
const displayDate=value=>new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(value+'T00:00:00Z'));

const prompts={
  discover:'Use Tawdheef. Read AGENTS.md and call get_agent_context and get_capabilities. Review my UAE directory and connected CV, then suggest a shortlist based on my role and location preferences. Do not send or submit anything.',
  apply:'Use Tawdheef. Read my selected companies and connected CV. Start an application run for these named targets, check for duplicates, and help me apply. Record each real outcome with its evidence. Hand off anything that needs my sign-in or approval.',
  review:'Use Tawdheef. Review my tracked applications and refresh replies for the relevant threads. Summarise real changes and next actions. Do not start new applications or send follow-ups.'
};
const code=(id,text)=>`<div class="install-line"><code id="${id}">${esc(text)}</code><button class="copy" type="button" data-copy="${id}" aria-label="Copy command">Copy</button></div>`;
const prompt=(id,text,label='Example prompt')=>`<div class="prompt"><div class="prompt-header"><span>${label}</span><button class="copy" type="button" data-copy="${id}" aria-label="Copy ${label.toLowerCase()}">Copy</button></div><pre id="${id}">${esc(text)}</pre></div>`;
const cta=(text,href,secondary=false)=>`<a class="button${secondary?' secondary':''}" href="${href}">${text}</a>`;
const faq=entries=>`<div class="faq">${entries.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div>`;
const directoryRow=pack=>`<article class="directory-row"><img class="flag" src="/flags/${esc(pack.country)}.svg" width="38" height="25" alt=""/><div class="directory-text"><h3><a href="/directories/${pack.id}/">${esc(pack.name)}</a></h3><p>${new Intl.NumberFormat('en').format(pack.recordCount)} companies &amp; sources · ${displayDate(pack.snapshotDate)}</p></div><div class="pack-actions"><a href="${packDownload(pack)}">Download</a><a href="${config.repositoryPublished?repository+'/tree/main/directories/'+pack.id:'/downloads/'+pack.id+'-source.json'}">${config.repositoryPublished?'GitHub':'Source'}</a></div></article>`;
const costCopy='Tawdheef is free and MIT licensed. Your AI client, model usage and connected providers may have their own plans or costs. Tawdheef does not require its own model API key.';
const tabbioCopy='Tabbio’s free plan lets you build, share and export a digital CV. Connect it to your agent so it can work from your current information. Tawdheef’s CV connection reads the CV you authorise; CV edits and analytics depend on the tools and permissions Tabbio exposes.';
const guidePages=createGuidePages({guides,config,firstRunPrompt,prompt,code});

function layout({title,description,path='/',body,active='',preview=false,home='/',wide=false}){
 const canonical=config.domain+path;
 return `<!doctype html><html lang="en"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover"/><meta name="theme-color" content="#FFFFFF"/><title>${esc(title)}</title><meta name="description" content="${esc(description)}"/><link rel="canonical" href="${canonical}"/>${preview?'<meta name="robots" content="noindex,nofollow"/>':''}<meta property="og:type" content="website"/><meta property="og:site_name" content="Tawdheef"/><meta property="og:title" content="${esc(title)}"/><meta property="og:description" content="${esc(description)}"/><meta property="og:url" content="${canonical}"/><meta property="og:image" content="${config.domain}/brand/github-social.png"/><meta name="twitter:card" content="summary_large_image"/><link rel="icon" href="/brand/favicon.svg" type="image/svg+xml"/><link rel="apple-touch-icon" href="/brand/apple-touch-icon.png"/><link rel="stylesheet" href="/site-assets/site.css"/></head><body><a class="skip" href="#main">Skip to content</a><header class="site-header"><a class="home" href="${home}" aria-label="tawdheef.com home"><img src="/brand/logo-latin-purple.svg" alt="tawdheef.com" width="194" height="36"/></a><div class="header-controls"><nav class="desktop-navigation" aria-label="Main navigation"><a href="/guides/" ${active==='guides'?'aria-current="page"':''}>Guides</a><a href="/directories/" ${active==='directories'?'aria-current="page"':''}>Directories</a><a href="/skills/" ${active==='skills'?'aria-current="page"':''}>Skills</a><a href="${repositoryHome}" target="_blank" rel="noreferrer">GitHub</a></nav><button class="mobile-menu-button" type="button" popovertarget="mobile-navigation">Menu</button><span class="header-start">${cta('Get started','/get-started/')}</span></div><div id="mobile-navigation" class="mobile-navigation" popover><nav aria-label="Mobile navigation"><a href="/get-started/">Get started</a><a href="/guides/">Guides</a><a href="/directories/">Directories</a><a href="/skills/">Agent skill</a><a href="${repositoryHome}" target="_blank" rel="noreferrer">GitHub</a></nav></div></header><div class="container${wide?' guides-container':''}"><main id="main">${body}</main><footer class="site-footer"><span>By <a href="${config.authorUrl}">Ahmed AlDhraif</a></span><span class="powered">Powered by <img src="/brands/tabbio.svg" width="14" height="14" alt=""/><a href="${config.tabbioUrl}?utm_source=tawdheef&utm_medium=footer">Tabbio</a></span><div class="links"><a href="/about/">About</a><a href="/guides/">Guides</a><a href="${repositoryHome}">GitHub</a><a href="/brand/">Brand</a><a href="/policies/#privacy">Privacy</a><a href="/policies/">Project policies</a><a href="/downloads/LICENSE.txt">MIT</a></div></footer></div><p class="toast" id="copy-status" role="status" aria-live="polite"></p><script src="/site-assets/site.js"></script></body></html>`;
}

function homePage(){return `
<section class="hero">
<h1>Auto-apply to jobs.<br/>Track your applications.</h1>
<p class="subtitle">Free, open-source software for you and your <span class="agent-options"><span class="agent-name"><img src="/brands/chatgpt.svg" width="20" height="20" alt=""/>ChatGPT</span> or <span class="agent-name"><img src="/brands/claude.svg" width="22" height="22" alt=""/>Claude</span> agent.</span></p>
<div class="actions">${cta('Get the free app','/get-started/')}<a class="hero-explainer" href="#walkthrough">See how it works</a></div>
<div class="creator-credit"><a class="creator-handle" href="${config.authorLinkedInUrl}" target="_blank" rel="noopener" aria-label="Built by Ahmed AlDhraif, view LinkedIn profile"><img class="credit-avatar" src="/site-assets/people/ahmed-aldhraif.png" width="32" height="32" alt="" decoding="async"/><span>Built by <strong>Ahmed AlDhraif</strong></span><img class="credit-linkedin" src="/brands/linkedin-original.ico" width="18" height="18" alt=""/></a></div>
</section>
${walkthrough()}
<div class="facts"><div><strong>Free & open source</strong><span>Open-source app.<br/>MIT licensed code.</span></div><div><strong>Saved locally</strong><span>Tracking is saved<br/>on your computer.</span></div><div><strong>${featuredPacks.length} country packs</strong><span>Use a directory.<br/>Help improve it.</span></div></div>
<section class="section" id="how-it-works"><h2>From company list to application.</h2><p>Job hunting turns into scattered tabs, old CVs and “did I already apply?” Tawdheef gives you and your agent the same place to work.</p><div class="workflow"><article><span class="step">1</span><div><h3>Start with a directory</h3><p>Choose a country pack or import your own list. Keep company sites, careers pages, contacts and source notes together.</p></div></article><article><span class="step">2</span><div><h3>Connect your CV</h3><p><a href="/get-started/#cv">Create a free Tabbio CV or connect the one you have</a>. Your agent uses your real experience and job preferences to find a fit.</p></div></article><article><span class="step">3</span><div><h3>Apply with a clear record</h3><p>Start a run for the targets you choose. Your agent helps through your authorised accounts and browser tools, then records real receipts and next actions.</p></div></article></div>${prompt('home-prompt',prompts.discover,'Try this with your agent')}<div class="actions">${cta('Get started','/get-started/')}${cta('Read the guides','/guides/',true)}</div></section>
<section class="section tabbio-section" id="tabbio" aria-labelledby="tabbio-title">
<div class="tabbio-heading"><a class="tabbio-brand" href="${config.tabbioUrl}" aria-label="Tabbio"><img src="/brands/tabbio-wordmark-violet-original.svg" width="144" height="35" alt="Tabbio"/></a><span class="free-label">Free digital CV</span></div>
<h2 id="tabbio-title">Your CV, ready for recruiters and agents.</h2>
<p class="tabbio-summary">Tabbio works worldwide.</p>
<ul class="cv-benefits">
<li><div class="benefit-heading"><span class="benefit-brands" aria-hidden="true"><img src="/brands/mcp-original.svg" width="22" height="22" alt=""/><svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="4" width="18" height="16" rx="3"/><path d="m7 9 3 3-3 3m6 0h4"/></svg></span><h3>A CV your agent can update</h3></div><p>Read, update and share your latest CV <span class="keep-word">through <a href="https://www.tabbio.com/en/mcp">MCP</a> or <a href="https://www.tabbio.com/en/cli">CLI</a>.</span></p></li>
<li><div class="benefit-heading"><span class="benefit-brands" aria-hidden="true"><img src="/brands/google-original.ico" width="22" height="22" alt=""/><img src="/brands/bing-original.ico" width="22" height="22" alt=""/></span><h3>Made to be found</h3></div><p>Publish a CV that Google, Bing, AI search and other agents can read.</p></li>
<li><div class="benefit-heading"><span class="benefit-brands" aria-hidden="true"><img src="/brands/tabbio.svg" width="22" height="22" alt=""/></span><h3>Open to work on Tabbio</h3></div><p>Show Tabbio employers you’re open to work so they can reach out.</p></li>
</ul>
<div class="identity-option"><img src="/brands/uae-pass-original.png" width="28" height="23" alt=""/><p>Optional identity verification with UAE PASS. <span>For eligible users; Tabbio is available worldwide.</span></p></div>
<div class="tabbio-actions">${cta('Create your free CV',config.tabbioSignupUrl+'?utm_source=tawdheef&utm_medium=website&utm_campaign=live_cv')}<a class="connect-existing" href="/get-started/#cv">Connect your CV</a></div>
<p class="tabbio-detail">Public CVs are eligible for search indexing. <a href="https://docs.tabbio.com/en/career/search-preview">About visibility</a></p>
</section>
<section class="section"><h2>Country packs. Built to be shared.</h2><p>Download a directory from GitHub and import it into Tawdheef. Add companies, fix links or contribute any country for others to use.</p>${featuredPacks.map(directoryRow).join('')}<div class="actions">${cta('How packs work','/directories/#how-packs-work',true)}${cta('Contribute on GitHub',contributeUrl,true)}</div></section>
<section class="section"><h2>Questions before you start?</h2>${faq([
 ['Is it really free?',costCopy+' <a href="/get-started/#privacy">See costs and connections</a>.'],
 ['Do I need to know how to code?','No coding is needed. Open the downloaded folder in Codex or Claude Code and ask your agent to set it up. Node.js 24 or newer is required. <a href="/guides/get-started/">Read the setup guide</a>.'],
 ['Does it apply for me?','Your agent can send emails and complete supported forms when you explicitly start a run for named targets. Sign-ins, CAPTCHAs, provider approvals and LinkedIn steps may need you. <a href="/guides/apply-to-jobs/">See how applications work</a>.'],
 ['Do I need Tabbio?','You can browse directories and track applications without Tabbio. Run requires a connected Tabbio CV. <a href="/guides/connect-your-cv/">Create or connect your free CV</a>.'],
 ['What does Tawdheef mean?','Tawdheef (توظيف) means employment in Arabic. The app is for job seekers anywhere; <a href="/directories/#contribute">directory contributions from any country are welcome</a>.'],
 ['Can I use it on my phone?','The website works on your phone. The local app and agent run on your computer, and the default server is available only there. <a href="/get-started/#privacy">See local requirements</a>.'],
 ['Where does my data go?','Your tracking records stay in a local database. AI, CV and email services connect online under their own permissions. <a href="/policies/#privacy">Read the privacy guide</a>.'],
 ['Can I add a country or fix a company?','Yes. Use a pack, fix a link or contribute a directory for any country. Packs include dated sources, not live vacancies. <a href="/directories/#contribute">Find packs and contribute</a>.']
])}</section><section class="closing"><h2>Ready to start?</h2><p>Start with the free app. Add a directory. Bring your agent.</p>${cta('Get Tawdheef','/get-started/')}</section>`;}

function skillsPage(){const installCommand=config.repositoryPublished?'npx skills@latest add ahmedaldhraif/tawdheef --skill tawdheef':'npx skills@latest add . --skill tawdheef';return `<div class="page-head"><h1>A skill for your<br/>job search.</h1><p>Help Codex or Claude Code find companies, use your CV and track applications in Tawdheef.</p><div class="actions">${cta('Set up Tawdheef','/get-started/#agent')}${cta('Read the skill guide','/skills/tawdheef/',true)}</div></div><div class="toc"><a href="#workflow">How it works</a><a href="#install">Install the skill</a><a href="#prompts">Try it</a><a href="/directories/">Directories</a></div><section class="section" id="workflow"><h2>One workflow. Your own agent.</h2><div class="skill-list"><a class="skill-item" href="/skills/tawdheef/"><span class="skill-icon" aria-hidden="true">ت</span><div><h3>Tawdheef</h3><p>Find companies, apply to chosen targets and track what happened.</p></div><span class="arrow" aria-hidden="true">›</span></a></div><div class="workflow"><article><span class="step">1</span><div><h3>Find companies</h3><p>Read a directory and check its sources. Employers, agencies and portals stay distinct.</p></div></article><article><span class="step">2</span><div><h3>Use your actual CV</h3><p>Match your experience and preferences. Ask you for anything missing.</p></div></article><article><span class="step">3</span><div><h3>Apply when you ask</h3><p>Start a run for named targets. Check duplicates and record real confirmations.</p></div></article><article><span class="step">4</span><div><h3>Keep track</h3><p>Review relevant replies and next steps. Scheduled checks never start applications.</p></div></article></div></section><section class="section" id="install"><h2>Install the skill.</h2><p>The <a href="/get-started/#agent">recommended app setup</a> installs it for your chosen client. To install guidance separately:</p>${code('skill-install',installCommand)}<p class="note">${config.repositoryPublished?'Choose Codex or Claude Code in the installer.':'Run from your downloaded Tawdheef folder and choose your client.'} A skill does not install the app, connect tools, sign into accounts or give permission to apply. <a href="/skills/tawdheef/#permissions">What it can do</a>.</p></section><section class="section" id="prompts"><h2>Ask for what you need.</h2><p>In Codex, start with <code>$tawdheef</code>. In Claude Code, use <code>/tawdheef</code>.</p>${prompt('discover',prompts.discover,'Find a shortlist')}${prompt('apply',prompts.apply,'Apply to selected targets')}${prompt('review',prompts.review,'Review progress')}<p class="note">Use the installed local client. ChatGPT and Claude web chats do not read local stdio settings. <a href="/get-started/#agent">Connect your local agent</a>.</p></section>`;}

function skillDetail(){const installCommand=config.repositoryPublished?'npx skills@latest add ahmedaldhraif/tawdheef --skill tawdheef':'npx skills@latest add . --skill tawdheef';return `<div class="page-head"><a class="back" href="/skills/">‹ All skills</a><h1>Tawdheef</h1><p>Instructions for using the local tracker with Codex or Claude Code.</p></div><div class="toc"><a href="#install">Install</a><a href="#use">Use it</a><a href="#workflow">Applications</a><a href="#permissions">Permissions</a></div><div class="docs-content"><h2 id="install">Start with the app.</h2><p><a href="/get-started/#agent">Let your agent set up Tawdheef</a>. That installs the skill and connects the project tools. To add only the skill:</p>${code('detail-install',installCommand)}<p>${config.repositoryPublished?'Choose your client in the installer.':'Run in your downloaded Tawdheef folder, then choose your client.'} Guidance alone does not install or start Tawdheef, connect MCP, or sign into an account.</p><h2 id="use">Use it in your client.</h2><div class="tabset" role="tablist" aria-label="Agent client"><button role="tab" id="codex-tab" aria-selected="true" aria-controls="codex-panel" tabindex="0">Codex</button><button role="tab" id="claude-tab" aria-selected="false" aria-controls="claude-panel" tabindex="-1">Claude Code</button></div><div id="codex-panel" role="tabpanel" aria-labelledby="codex-tab">${prompt('codex-skill','$tawdheef\n'+prompts.discover,'Codex prompt')}</div><div id="claude-panel" role="tabpanel" aria-labelledby="claude-tab" hidden>${prompt('claude-skill','/tawdheef\n'+prompts.discover,'Claude Code prompt')}</div><p>Open this folder in the local client and accept its project/server trust prompt. ChatGPT and Claude web chats do not read local stdio configuration.</p><h2 id="workflow">How applications work.</h2><ol><li>Read a <a href="/directories/">directory</a>, its source evidence and your actual CV.</li><li>Choose targets and explicitly start a run. Research alone does not authorize sending.</li><li>The agent checks duplicates, uses your authorized browser or email connection, and records real outcomes.</li><li>Review receipts, relevant replies and anything marked <strong>Needs you</strong>.</li></ol><p>A draft, a created profile, an uploaded CV and a submitted application are different steps. An application needs a real receipt or confirmation. After an uncertain submission, inspect before retrying.</p><h2 id="permissions">Your accounts. Your permission.</h2><p>Enter credentials and complete sign-ins in <strong>Connections</strong>, never in chat. The app’s Run button requires a <a href="/get-started/#cv">connected Tabbio CV</a>. Browser applications can work without email.</p><p>Sign-ins, CAPTCHA, identity declarations and provider approvals may need you. LinkedIn application steps stay manual. A skill cannot bypass client or provider restrictions. Calendar actions need separate consent; scheduled checks never start applications or send follow-ups.</p><h2 id="help">Source and help.</h2><p>The app includes the skill, its references, <code>docs/FIRST-RUN.md</code> for setup and <code>docs/AGENT-GUIDE.md</code> for tools and recovery. <a href="/get-started/#agent">Setup guide</a> · <a href="/policies/#privacy">Privacy</a>.</p><div class="actions">${cta('Get the app','/get-started/')}${cta('Download skill source','/downloads/tawdheef-skill.zip',true)}</div></div>`;}

function setupPage(){
 const setupPrompt=firstRunPrompt;
 return `<div class="page-head"><h1>From download<br/>to your first application.</h1><p>Your agent handles setup. You sign in, connect your CV and choose where to apply.</p></div>
<div class="toc"><a href="#install">Get the app</a><a href="#agent">Set up your agent</a><a href="#cv">Connect your CV</a><a href="#privacy">Costs & privacy</a></div>
<div class="docs-content">
<h2 id="install">1. Get Tawdheef from GitHub.</h2><p>Download the source ZIP and extract it. Open the extracted folder in your installed, signed-in <strong>Codex or Claude Code</strong>. You only need one.</p>
<div class="actions">${cta('Download from GitHub',sourceDownload)}${cta('View source',repositoryHome,true)}</div>
<p class="source-status"><a href="${releaseUrl}">Release notes and checksums</a>. This is a source app for your computer; <a href="https://nodejs.org/en/download">Node.js 24 or newer</a> is required.</p>
<details><summary>Prefer Git?</summary>${code('clone-app','git clone '+repository+'.git')}${code('open-folder','cd tawdheef')}<p>Open this folder in your assistant, then follow the same steps below.</p></details>
<h2 id="agent">2. Ask your agent to set it up.</h2><p>Paste this into Codex or Claude Code:</p>${prompt('first-run-prompt',setupPrompt,'Setup request')}
<p>Your agent checks dependencies, starts the local app and prepares project tools. Accept the project/server trust prompt when shown. A new chat may be needed to load MCP tools.</p>
<p>ChatGPT and Claude web chats do not read local stdio settings. Use the local client above. <a href="/skills/">Read the agent skill</a>.</p>
<details id="manual"><summary>Prefer manual setup?</summary><p>In a terminal in the extracted folder:</p>${code('manual-start','npm start')}<p>This installs missing locked dependencies, builds the screen and starts <a href="http://127.0.0.1:4000/">your local tracker</a>. On Windows, you can also open <strong>Start Tawdheef.cmd</strong>.</p><p>Add browser tools, then run only the command for your chosen client:</p>${code('manual-browser','npm run setup -- --browser')}${code('manual-codex','npm run agent -- codex --browser')}${code('manual-claude','npm run agent -- claude-code --browser')}<p>These prepare project settings and the skill. Sign-ins are separate. Preserve custom settings if a conflict is reported; follow <a href="${repository}/blob/main/docs/FIRST-RUN.md">the setup guide</a>.</p></details>
<h2 id="cv">3. Create or connect your free CV.</h2><p>Keep one current CV in Tabbio for recruiters and your agent. Available worldwide. Already have one? Connect it in the app.</p>
<div class="actions">${cta('Create your free CV',config.tabbioSignupUrl+'?utm_source=tawdheef&utm_medium=setup&utm_campaign=live_cv')}${cta('Tabbio connection guide','https://www.tabbio.com/en/mcp',true)}</div>
<ol><li>Create your CV in Tabbio using your real experience.</li><li>In Tawdheef, open <strong>Connections → Tabbio CV → Connect</strong> and complete sign-in.</li><li>Choose your assistant under <strong>AI assistants</strong>, then use <strong>Check connections</strong>.</li></ol>
<p>A successful check confirms the app can read your CV and your selected assistant is signed in. A connected CV is required for <strong>Run</strong>; browsing directories and manual tracking work without it.</p>
<details id="tabbio-agent"><summary>Want your agent to update your CV too?</summary><p>Tawdheef reads your CV. For CV editing and sharing, connect Tabbio directly to your agent through its own <a href="https://www.tabbio.com/en/mcp">MCP or CLI</a>. These are separate connections.</p>${prompt('cv-agent-prompt','Help me connect Tabbio using its official MCP or CLI guide. Read my current CV, ask me for missing facts and help keep it up to date. Show proposed edits before changing it. Ask before publishing it, changing employer visibility or turning on Open to work. Do not invent experience.','Tabbio agent request')}<p>Use Tabbio’s <a href="https://www.tabbio.com/en/mcp">current setup instructions</a> and complete sign-in yourself. Free connection and CV tools are available; paid AI features have their own limits.</p></details>
<p>Email is optional for browser applications. Connect a mailbox for email applications and reply checks. Gmail and Outlook need your own OAuth registration or a supported bridge; your agent can guide you. Calendar and schedules can wait.</p>
<h2 id="first-run">4. Choose a directory. Start a run.</h2><p>The UAE starter directory is included. Add another <a href="/directories/#how-packs-work">country pack</a> or import your own list.</p><p>Open <strong>Run</strong>, set your role and location preferences, and choose companies. Your agent uses your accounts and records confirmations and replies. Sign-ins, CAPTCHA and required declarations may need you; LinkedIn applications stay manual.</p><p>Want a shortlist first? Ask your agent:</p>${prompt('setup-prompt',prompts.discover,'Find a shortlist')}
<p><a href="/skills/tawdheef/#workflow">How applications work</a> · <a href="/directories/#contribute">Help improve a directory</a>.</p>
<h2 id="privacy">Costs, privacy and local requirements.</h2><p>${costCopy}</p><p>The app and agent run on your computer. Your private tracker is available there by default; this website does not host it or make it available on your phone.</p><p>Tracking and credentials are stored locally. Credentials are not encrypted at rest by the app. Connected AI, Tabbio, email and careers services communicate online under their own permissions. <a href="/policies/#privacy">Read the privacy guide</a>.</p><p>This website has no visitor analytics scripts or tracking pixels. Hosting may keep access logs. Tabbio links include readable referral parameters; its own plans and privacy terms apply.</p>
<h2 id="help">Something needs attention?</h2><p>Find a practical fix in the <a href="/guides/troubleshoot/">troubleshooting guide</a>, or browse <a href="/guides/">all guides</a>.</p><p>Use <strong>Connections → Check connections</strong>, or ask your agent to check setup again. <code>npm run doctor</code> reports installed tools. Read the <a href="${repository}/blob/main/docs/FIRST-RUN.md">setup checklist</a> or <a href="${repository}/blob/main/docs/AGENT-GUIDE.md">agent guide</a> for recovery steps.</p>
</div><section class="closing"><h2>Already running?</h2><p>Return to your local workspace.</p>${cta('Open local tracker','http://127.0.0.1:4000/')}</section>`;
}

function directoryPage(){return `<div class="page-head"><h1>Country directories.<br/>Shared on GitHub.</h1><p>Free directory packs for Tawdheef. Start with the GCC, add your country or help keep a list current.</p></div>
<section class="section pack-list"><h2>Choose a pack.</h2><p>Each download comes from GitHub Releases and includes import files and original sources.</p>${featuredPacks.map(directoryRow).join('')}<p class="note">Dated research lists, not live job feeds. <a href="/directories/uae/">Original UAE starter snapshot</a>.</p></section>
<section class="section" id="how-packs-work"><h2>A pack adds a company list.</h2><p>It adds organisations, careers links and source notes to your local tracker. It does not install code or apply to jobs.</p><div class="workflow"><article><span class="step">1</span><div><h3>Download and extract</h3><p>Choose a country above and extract its ZIP from GitHub.</p></div></article><article><span class="step">2</span><div><h3>Add it to Tawdheef</h3><p>Create or select a directory, then choose <strong>List options → Import list</strong>. Select a CSV from the pack and review the preview.</p></div></article><article><span class="step">3</span><div><h3>Use it with your agent</h3><p>Import every numbered CSV part into the same directory. Your agent can now read the list, match it to your CV and help you apply.</p></div></article></div><p><a href="${repository}/blob/main/docs/AGENT-DIRECTORIES.md">Agent and CLI instructions</a> · <a href="/get-started/#cv">Connect your Tabbio CV</a>.</p></section>
<section class="section" id="contribute"><h2>Your correction helps the next person.</h2><p>Add a company, fix a link or share a pack from any country. Open an issue with a public source; no coding needed. Developers can send a pull request.</p><div class="actions">${cta('Add or fix a company',dataIssueUrl)}${cta('Suggest a country pack',countryIssueUrl,true)}</div><p><a href="${contributeUrl}">Contribution guide</a> · <a href="${repository}/tree/main/directories/_template">Pack template on GitHub</a>.</p><p class="note">Initial research by Ahmed AlDhraif. Community contributions welcome. Accepted changes become available for everyone in the repository and a future pack release.</p></section>
<section class="section"><h2>Already have a list?</h2><p>Import your own CSV or Excel file through <strong>List options → Import list</strong>. Keep it private, or contribute public recruitment data on GitHub.</p>${cta('Get Tawdheef','/get-started/',true)}</section>`;}

function countryPackPage(pack){
 const index=packIndices.get(pack.id);
 const roleRows=Object.entries(pack.sourceRoleCounts).sort((a,b)=>b[1]-a[1]).map(([role,n])=>`<li><span>${esc(role)}</span><span>${new Intl.NumberFormat('en').format(n)}</span></li>`).join('');
 const examples=index.records.slice(0,30).map(record=>{const url=[record.careersUrl,record.website].find(value=>/^https?:\/\//i.test(value||''));return `<tr><td>${esc(record.name)}</td><td>${esc(record.sourceRole)}</td><td>${url?`<a href="${esc(url)}" target="_blank" rel="noreferrer">${record.careersUrl===url?'Careers page':'Website'}</a>`:'See source notes'}</td></tr>`;}).join('');
 const indexUrl=config.repositoryPublished?`https://raw.githubusercontent.com/ahmedaldhraif/tawdheef/main/directories/${pack.id}/index.json`:`/downloads/${pack.id}-index.json`;
 const fullSource=config.repositoryPublished?repository+'/tree/main/directories/'+pack.id:`/downloads/${pack.id}-source.json`;
 return `<div class="page-head"><a class="back" href="/directories/">‹ All directories</a><h1>${esc(countryTitle(pack))} company directory.</h1><p>${new Intl.NumberFormat('en').format(pack.recordCount)} organisations and recruitment sources for your job search. Free to use with Tawdheef and your agent.</p></div><div class="pack-meta"><div><strong>${new Intl.NumberFormat('en').format(pack.recordCount)}</strong>company &amp; source records</div><div><strong>${displayDate(pack.snapshotDate)}</strong>research snapshot</div><div><strong>Free</strong>country directory pack</div></div><div class="actions country-actions">${cta('Download pack',packDownload(pack))}${cta('View on GitHub',fullSource,true)}</div><p class="note">Research leads, not live job offers. Campuses, branches and unresolved sources may appear separately.</p><section class="section"><h2>What’s inside</h2><p>Company names, careers routes, published contacts and dated source notes. Each record keeps its original source ID and evidence.</p><details class="pack-coverage"><summary>Source types and coverage</summary><ul>${roleRows}</ul></details><p class="note">Import the CSV files in Tawdheef through <strong>List options → Import list</strong>. Preview first. If the pack has numbered parts, import each into the same directory.</p></section><section class="section"><h2>A look at the directory</h2><div class="data-preview"><table><thead><tr><th scope="col">Organisation / source</th><th scope="col">Source role</th><th scope="col">Published route</th></tr></thead><tbody>${examples}</tbody></table></div><p class="note">Showing ${Math.min(30,index.records.length)} of ${new Intl.NumberFormat('en').format(pack.recordCount)} records. The download includes the full directory.</p></section><section class="section"><h2>For your agent</h2><p>Read the compact JSON index, then follow the source ID to the full evidence. The pack includes a manifest, checksums and import files.</p><div class="actions">${cta('Read JSON index',indexUrl,true)}${cta('Get Tawdheef','/get-started/',true)}</div><p><a href="${repository}/blob/main/docs/AGENT-DIRECTORIES.md">Agent download and CLI import steps</a> · <a href="/get-started/#cv">Create or connect your free Tabbio CV</a>.</p></section><section class="section"><h2>Help keep it useful.</h2><p>Add a company, fix a link or contribute another country.</p>${cta('Add or fix a company',dataIssueUrl,true)}<p><a href="${contributeUrl}">Contribution guide</a> · <a href="${countryIssueUrl}">Suggest a country pack</a>.</p></section>`;
}

function policiesPage(){return `<div class="page-head"><h1>About this project.</h1><p>Tawdheef is an independent open-source project maintained by Ahmed AlDhraif. The Tabbio integration connects to its separate CV service.</p></div><div class="docs-content"><h2>Free and open source</h2><p>The code is MIT licensed. You can use, modify, fork and redistribute it, including commercially, while keeping the licence and copyright notice. The licence includes warranty and liability disclaimers; it does not guarantee immunity from legal claims.</p><p><a href="/downloads/LICENSE.txt">Read the MIT licence</a> · <a href="${policyUrl('docs/policies/PROJECT.md')}">Project policy</a></p><h2 id="privacy">Your data</h2><p>The tracker stores your records and credentials locally. They are not encrypted by the app. Connected AI, email and CV services process data under their own terms and permissions.</p><p>The website has no first-party analytics scripts or tracking pixels. Hosting services may keep access logs. Links to Tabbio include readable referral parameters.</p><p><a href="${policyUrl('docs/policies/PRIVACY.md')}">Privacy details</a></p><h2>Directory sources</h2><p>Directories are dated research lists, not job offers or verified vacancies. Check the source before acting. Use public recruitment information and respect the rights attached to each source.</p><p><a href="${policyUrl('docs/policies/DATA.md')}">Data and corrections</a> · <a href="${contributeUrl}">Suggest a correction or removal</a></p><h2>Names and logos</h2><p>A fork is your own project. Do not present it as an official Tawdheef, Ahmed AlDhraif or Tabbio service, or imply their endorsement. Third-party brands keep their own rights.</p><p><a href="${policyUrl('docs/policies/TRADEMARKS.md')}">Brand use</a></p><h2>Responsible use</h2><p>Use accounts and information you are authorised to access. Follow applicable law and provider rules. Do not use project spaces for spam, impersonation, harassment or publishing private information.</p><p>These community and service policies do not add restrictions to the MIT code licence. Forks and connected services have their own operators.</p><p><a href="${policyUrl('docs/policies/RESPONSIBLE-USE.md')}">Responsible use</a> · <a href="${config.repositoryPublished?repository+'/blob/main/CODE_OF_CONDUCT.md':'/downloads/code-of-conduct.md'}">Community conduct</a></p><h2>Security</h2><p>Report vulnerabilities privately through the repository’s Security page. Do not post CVs, credentials or private tracking records in public issues.</p><p><a href="${config.repositoryPublished?repository+'/security/advisories/new':'/downloads/security.md'}">Report a vulnerability</a></p></div>`;}

function uaePage(){
 const roles=[...new Set(source.records.map(r=>r.sourceRole).filter(Boolean))].sort();
 const rows=source.records.map(record=>`<tr data-directory-row data-role="${esc(record.sourceRole)}"><td>${esc(record.name)}</td><td>${esc(record.sourceRole||'Not classified')}</td><td>${record.careersUrl&&/^https?:\/\//i.test(record.careersUrl)?`<a href="${esc(record.careersUrl)}" target="_blank" rel="noreferrer">Careers page</a>`:'Route not confirmed'}</td></tr>`).join('');
 return `<div class="page-head"><a class="back" href="/directories/">‹ All directories</a><h1>UAE careers directory.<br/>Ready for your agent.</h1><p>A free, open-source research pack of ${count} organisations and recruitment sources. Use it with Tawdheef to plan your search and track what happens.</p></div><div class="pack-meta"><div><strong>${count}</strong>organisation & source records</div><div><strong>10 Nov 2026</strong>research snapshot</div><div><strong>Free</strong>included in Tawdheef</div></div><div class="actions">${cta('Get the app & directory','/get-started/')}${cta('Download from GitHub',packDownload(packs.find(pack=>pack.id==='uae')),true)}</div><div class="notice">This is a dated source directory, not a live list of vacancies. It includes employers, agencies, portals and programmes. Published links may be untested; inclusion does not confirm hiring, eligibility or permission to automate.</div><section class="section"><h2>Explore the sources.</h2><p>Search the directory and filter by source role. The full pack retains stable source IDs, original hyperlinks, evidence and missing-data notes.</p><div class="directory-tools"><input type="search" id="directory-search" placeholder="Search organisations or source types" aria-label="Search UAE directory"/><select id="source-role" aria-label="Filter by source role"><option value="">All source roles</option>${roles.map(role=>`<option value="${esc(role)}">${esc(role)}</option>`).join('')}</select></div><div class="data-preview"><table><thead><tr><th scope="col">Organisation / source</th><th scope="col">Source role</th><th scope="col">Published route</th></tr></thead><tbody>${rows}</tbody></table><p class="pack-empty" id="directory-empty" hidden>No sources match. Try another name or source role.</p></div><p class="count-label" id="directory-count" role="status">${count} source records</p></section><section class="section"><h2>Use it with Tawdheef.</h2><p>The UAE pack is bundled with a fresh install. Your agent can review the sources alongside your authorised CV and preferences, then suggest useful starting points.</p>${prompt('uae-prompt',prompts.discover,'UAE research prompt')}<p class="note">Adding the pack does not apply to any organisation. Start a named application run when you want your agent to act.</p><div class="actions">${cta('Set up Tawdheef','/get-started/')}${cta('Read the skill guide','/skills/tawdheef/',true)}</div></section><section class="section"><h2>Use your current CV.</h2><p>Keep a digital CV in Tabbio and connect it when you want your agent to use it. The directory provides leads; your CV provides the context.</p><a class="tabbio-link" href="${config.tabbioSignupUrl}?utm_source=tawdheef&utm_medium=directory&utm_campaign=uae"><img src="/brands/tabbio.svg" width="22" height="22" alt=""/>Build your free Tabbio CV</a></section>`;
}

